  "inlineSchema": "// Schéma Prisma - Netflix du Mouvement\n// PostgreSQL + Prisma Client\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Genre {\n  HOMME\n  FEMME\n  MIXTE\n}\n\n// Coach qui anime la séance — indépendant de `genre` (public cible). DUO = séance\n// animée par le coach homme et la coach femme ensemble.\nenum Coach {\n  FEMME\n  HOMME\n  DUO\n}\n\nenum Niveau {\n  DEBUTANT\n  INTERMEDIAIRE\n  AVANCE\n}\n\nenum RoleUtilisateur {\n  USER\n  ADMIN\n}\n\nenum JourSemaine {\n  LUNDI\n  MARDI\n  MERCREDI\n  JEUDI\n  VENDREDI\n  SAMEDI\n  DIMANCHE\n}\n\n// -----------------------------\n// UTILISATEURS\n// -----------------------------\nmodel User {\n  id             String          @id @default(cuid())\n  email          String          @unique\n  password       String?\n  googleId       String?         @unique\n  prenom         String\n  role           RoleUtilisateur @default(USER)\n  xp             Int             @default(0)\n  streak         Int             @default(0)\n  dernierPassage DateTime?\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  progressions  UserProgress[]\n  evaluations   Evaluation[]\n  favoris       Favori[]\n  badges        UserBadge[]\n  seancesFaites SeanceHistorique[]\n  engagements   EngagementHebdomadaire[]\n}\n\n// -----------------------------\n// CATALOGUE : SÉANCES (façon \"titres Netflix\")\n// -----------------------------\nmodel Seance {\n  id            String   @id @default(cuid())\n  titre         String\n  titreEn       String?\n  description   String?\n  descriptionEn String?\n  genre         Genre    @default(MIXTE)\n  coach         Coach    @default(DUO)\n  niveau        Niveau   @default(DEBUTANT)\n  dureeMin      Int      @default(20)\n  imageUrl      String?\n  categorie     String? // ex: \"Mobilité\", \"Pilates\", \"Renforcement\"\n  categorieEn   String?\n  ordre         Int      @default(0)\n  createdAt     DateTime @default(now())\n\n  mouvements  SeanceMouvement[]\n  historique  SeanceHistorique[]\n  engagements EngagementHebdomadaire[]\n}\n\n// -----------------------------\n// BIBLIOTHÈQUE DE MOUVEMENTS\n// -----------------------------\nmodel Mouvement {\n  id                   String   @id @default(cuid())\n  nom                  String\n  nomEn                String?\n  description          String?\n  descriptionEn        String?\n  videoUrl             String   @default(\"https://storage.googleapis.com/coverr-main/mp4/Mt_Baker.mp4\")\n  cfStreamUid          String?\n  cfStreamStatus       String? // null | \"uploading\" | \"ready\" | \"error\"\n  muscleprincipal      String?\n  muscleprincipalEn    String?\n  musclesSecondaires   String[] @default([])\n  musclesSecondairesEn String[] @default([])\n  niveau               Niveau   @default(DEBUTANT)\n  materiel             String[] @default([])\n  materielEn           String[] @default([])\n  erreursFrequentes    String[] @default([])\n  erreursFrequentesEn  String[] @default([])\n  regression           String?\n  regressionEn         String?\n  progression          String?\n  progressionEn        String?\n  dureeConseillee      Int? // en secondes\n  createdAt            DateTime @default(now())\n\n  seances SeanceMouvement[]\n  favoris Favori[]\n}\n\n// Table de jointure Séance <-> Mouvement avec ordre d'exécution\nmodel SeanceMouvement {\n  id          String    @id @default(cuid())\n  seance      Seance    @relation(fields: [seanceId], references: [id], onDelete: Cascade)\n  seanceId    String\n  mouvement   Mouvement @relation(fields: [mouvementId], references: [id], onDelete: Cascade)\n  mouvementId String\n  ordre       Int       @default(0)\n  series      Int?\n  repetitions String? // ex: \"12\" ou \"30 sec\"\n\n  @@unique([seanceId, mouvementId])\n}\n\n// -----------------------------\n// PROGRESSION / HISTORIQUE\n// -----------------------------\nmodel SeanceHistorique {\n  id        String   @id @default(cuid())\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId    String\n  seance    Seance   @relation(fields: [seanceId], references: [id], onDelete: Cascade)\n  seanceId  String\n  terminee  Boolean  @default(false)\n  xpGagne   Int      @default(0)\n  createdAt DateTime @default(now())\n}\n\n// Engagement pris par l'utilisateur à suivre une séance régulièrement, un\n// jour de semaine fixe, pendant au moins `dureeSemaines` semaines.\nmodel EngagementHebdomadaire {\n  id            String      @id @default(cuid())\n  user          User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId        String\n  seance        Seance      @relation(fields: [seanceId], references: [id], onDelete: Cascade)\n  seanceId      String\n  jour          JourSemaine\n  dureeSemaines Int         @default(4)\n  dateDebut     DateTime    @default(now())\n  createdAt     DateTime    @default(now())\n\n  @@unique([userId, seanceId])\n}\n\nmodel UserProgress {\n  id            String   @id @default(cuid())\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId        String\n  scoreMobilite Int      @default(0)\n  scoreForce    Int      @default(0)\n  scorePosture  Int      @default(0)\n  poids         Float?\n  tourDeTaille  Float?\n  createdAt     DateTime @default(now())\n}\n\nmodel Evaluation {\n  id             String   @id @default(cuid())\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId         String\n  test           String // ex: \"mobilite_hanches\"\n  resultat       String\n  recommandation String?\n  createdAt      DateTime @default(now())\n}\n\nmodel Favori {\n  id          String    @id @default(cuid())\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId      String\n  mouvement   Mouvement @relation(fields: [mouvementId], references: [id], onDelete: Cascade)\n  mouvementId String\n\n  @@unique([userId, mouvementId])\n}\n\nmodel Badge {\n  id           String      @id @default(cuid())\n  nom          String\n  description  String?\n  icone        String?\n  utilisateurs UserBadge[]\n}\n\nmodel UserBadge {\n  id       String   @id @default(cuid())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId   String\n  badge    Badge    @relation(fields: [badgeId], references: [id], onDelete: Cascade)\n  badgeId  String\n  obtenuLe DateTime @default(now())\n\n  @@unique([userId, badgeId])\n}\n",
